/* =========================================================
   DATA — vollständiger Unfallatlas 2020-2024 (destatis.de), 100% der
   polizeilich erfassten Unfälle mit Personenschaden, keine Stichprobe/
   Hochrechnung mehr. Quellen: Unfallorte2020_LinRef.csv, Unfallorte_2021_
   LinRef.txt, Unfallorte2022_LinRef.csv, Unfallorte2023_LinRef.csv,
   Unfallorte2024_LinRef.csv.
   columns: [lat, lon, land, month, weekday, hour, kategorie, art, typ1, licht, strasse, participantMask, year]
   Row count: 1.270.879 (2020: 237.994 · 2021: 238.826 · 2022: 256.492 ·
   2023: 269.048 · 2024: 268.519).
   Zeilenweise als kompaktes Binärformat (19 Byte/Zeile: lat/lon als Int32
   ×1e6, restliche Felder als Uint8) base64-kodiert eingebettet statt als
   riesiges JSON-Array-Literal — Download/Parse-Zeit bleibt dadurch trotz
   ~4x mehr Zeilen (100% statt 25%-Stichprobe) handhabbar. Wird beim Laden
   synchron in dieselbe ACC_DATA-Array-of-Arrays-Struktur entpackt wie
   zuvor, keine andere Datei musste dafür geändert werden.
   ========================================================= */
const ACC_DATA_B64="";
const ACC_DATA = (function(){
  const bin = atob(ACC_DATA_B64);
  const len = bin.length;
  const buf = new Uint8Array(len);
  for(let i=0;i<len;i++) buf[i] = bin.charCodeAt(i);
  const dv = new DataView(buf.buffer);
  const REC = 19;
  const n = (len / REC) | 0;
  const out = new Array(n);
  for(let i=0;i<n;i++){
    const o = i*REC;
    const lat = dv.getInt32(o, true) / 1e6;
    const lon = dv.getInt32(o+4, true) / 1e6;
    out[i] = [
      lat, lon,
      buf[o+8], buf[o+9], buf[o+10], buf[o+11], buf[o+12], buf[o+13],
      buf[o+14], buf[o+15], buf[o+16], buf[o+17], buf[o+18]+2000
    ];
  }
  return out;
})();
